-- Plan with AI: the Property department's master schedule as a schedule type (`property-development`,
-- project type Properties). Source of truth: src/planner/catalogs/propertyDevelopment.ts (from the
-- department's "Property Development Project Schedule Template"); src/db/propertyDevelopment.test.ts
-- checks that this seed and the module agree.
--
-- The catalog gains three optional columns, shown in the sheets the planner creates:
--   activity_id     the template's activity id (P010 ... P440)
--   responsibility  lead responsibility (Development, Design / Consultant, Main Contractor, ...)
--   criteria        completion / release criteria of the activity or gate
--
-- PLACEHOLDER DEFAULTS, NOT REAL HISTORY: the template imposes no durations; default_days are
-- representative working days for a mid-size residential or mixed-use development so that the
-- planner can draft a first cut. Load completed projects into history_projects to replace them.
--
-- The target is P420 "Complete planned handover"; the defects period and close-out (P430, P440)
-- follow it in the catalog logic, which the planner allows for activities the catalog places after
-- the target.

alter table activity_catalog
  add column activity_id text check (activity_id is null or length(activity_id) between 1 and 40),
  add column responsibility text check (responsibility is null or length(responsibility) <= 200),
  add column criteria text check (criteria is null or length(criteria) <= 1000);


